private static void findMax(int[] samples) {
    maxIndex.clear();
    maxNumber = samples[0];
    int leftCount = 0; //已经从左侧记录的下标个数，用于保证下标升序排列
    int i = 0;
    int j = samples.length - 1;
    while(i <= j) {
        //处理左侧指针指向的元素
        if(samples[i] > maxNumber) {
            maxNumber = samples[i];
            maxIndex.clear();
            leftCount = 0;
        }
        if(samples[i] == maxNumber) {
            maxIndex.add(leftCount, i);
            leftCount ++;
        }
        //处理右侧指针指向的元素，两指针相遇时中间的元素只记录一次
        if(i != j) {
            if(samples[j] > maxNumber) {
                maxNumber = samples[j];
                maxIndex.clear();
                leftCount = 0;
            }
            if(samples[j] == maxNumber) {
                maxIndex.add(leftCount, j);
            }
        }
        i ++;
        j --;
    }
}
